<?php require_once 'includes/db.php';header('Content-Type: application/json');$raw=file_get_contents('php://input');file_put_contents(__DIR__.'/mpesa_callback.log',date('c').' '.$raw.PHP_EOL,FILE_APPEND);$d=json_decode($raw,true);$r=$d['Body']['stkCallback']??null;if(!$r){echo json_encode(['ResultCode'=>1,'ResultDesc'=>'Invalid callback']);exit;}$id=$r['CheckoutRequestID']??'';$code=(int)($r['ResultCode']??1);if($id){if($code===0){$receipt=null;foreach($r['CallbackMetadata']['Item']??[] as $i)if(($i['Name']??'')==='MpesaReceiptNumber'){$receipt=$i['Value']??null;break;}db()->prepare("UPDATE orders SET payment_status='Paid',order_status='Processing',mpesa_receipt=? WHERE checkout_request_id=?")->execute([$receipt,$id]);}else db()->prepare("UPDATE orders SET payment_status='Failed' WHERE checkout_request_id=?")->execute([$id]);}echo json_encode(['ResultCode'=>0,'ResultDesc'=>'Accepted']);